diff --git a/store.test.mjs b/store.test.mjs
new file mode 100644
index 0000000..9b4cfce
--- /dev/null
+++ b/store.test.mjs
@@ -0,0 +1,28 @@
+import { strict as assert } from "node:assert";
+import test from "node:test";
+
+import { createPlanningStore } from "./store.mjs";
+
+const taskId = "task-1";
+const acceptedReport = JSON.stringify({ status: "ready", task_id: taskId });
+const malformedReport = "{not valid json";
+
+function assertRejectedWithoutCanonicalReplacement(store, expectedCanonicalRaw) {
+  const result = store.publish(taskId, malformedReport);
+
+  assert.deepEqual(result, { status: "rejected", reason: "invalid_json" });
+  assert.equal(store.canonicalRaw, expectedCanonicalRaw);
+}
+
+test("rejects a malformed report without creating canonical state in a fresh store", () => {
+  const store = createPlanningStore();
+
+  assertRejectedWithoutCanonicalReplacement(store, null);
+});
+
+test("rejects a malformed report without replacing an existing accepted report", () => {
+  const store = createPlanningStore();
+  assert.equal(store.publish(taskId, acceptedReport).status, "accepted");
+
+  assertRejectedWithoutCanonicalReplacement(store, acceptedReport);
+});

